INSERT INTO plant_directory (botanical_name, common_name, category, sub_category, origin_regions, optimal_climate, soil_requirements, growth_cycle_days, water_needs, description) VALUES
('Rhizobium spp.','Rhizobium Inoculant','microbes','Nitrogen Fixer','["Global"]','{"temp_min":15,"temp_max":35,"rainfall_min":0,"rainfall_max":0}','{"ph_min":6.0,"ph_max":7.5,"type":["all"],"drainage":"all"}',0,'N/A','Symbiotic nitrogen fixer for legumes. 200g inoculant treats 10 kg seed. Increases pulse yield 15-25%.'),
