INSERT INTO plant_directory (botanical_name, common_name, category, sub_category, exotic_variety, heirloom, origin_regions, optimal_climate, soil_requirements, growth_cycle_days, water_needs, description) VALUES
('Piper betle','Magahi Paan (Betel Leaf)','beverages','Heirloom Herb',FALSE,TRUE,'["Bihar","Magadh Region"]','{"temp_min":18,"temp_max":35,"rainfall_min":1000,"rainfall_max":2000}','{"ph_min":6.0,"ph_max":7.5,"type":["loam","clay loam"],"drainage":"well"}',180,'High','GI-tagged Magahi betel leaf from Magadh region of Bihar. Distinctive aroma and taste. Cultivated under shade nets in Nalanda, Nawada, and Gaya districts. A single vine produces 100-120 leaves per year.'),
('Oryza sativa','Katarani Rice (Magahi Red Rice)','staple','Heirloom Cereal',FALSE,TRUE,'["Bihar","Magadh"]','{"temp_min":22,"temp_max":35,"rainfall_min":1200,"rainfall_max":2000}','{"ph_min":5.5,"ph_max":7.0,"type":["clay","loam"],"drainage":"poor"}',140,'High','Ancient red rice variety native to Magadh region. Rust-colored grain with nutty flavor. Rich in anthocyanins and iron. Traditionally grown in lowland paddies of Nalanda and Gaya districts. Drought-resistant landrace.'),
('Euryale ferox','Desi Makhana (Fox Nut)','produce','Aquatic Crop',FALSE,TRUE,'["Bihar","North India"]','{"temp_min":20,"temp_max":35,"rainfall_min":1000,"rainfall_max":2000}','{"ph_min":6.0,"ph_max":8.0,"type":["clay","loam"],"drainage":"pond"}',240,'Aquatic','Bihar produces 90% of the world's makhana. Grown in freshwater ponds across Darbhanga, Madhubani, and Purnea. Popped seeds are a superfood — high protein, low fat. Harvested by skilled farmers wading through water.'),
('Solanum melongena','Bihar Heirloom Brinjal (Baigan)','produce','Heirloom Vegetable',FALSE,TRUE,'["Bihar","India"]','{"temp_min":20,"temp_max":32,"rainfall_min":600,"rainfall_max":1000}','{"ph_min":5.5,"ph_max":7.0,"type":["loam","sandy loam"],"drainage":"well"}',70,'Medium','Traditional Bihar variety — large, glossy purple-black fruits with green calyx. Non-GMO, non-hybrid. Sweet flesh with fewer seeds. Thrives in Gangetic plain conditions. Seed-saving possible.'),
('Oryza sativa','Sona Chur Rice (Golden Dust)','staple','Heirloom Aromatic',FALSE,TRUE,'["Bihar","West Bengal"]','{"temp_min":22,"temp_max":35,"rainfall_min":1000,"rainfall_max":1800}','{"ph_min":5.5,"ph_max":7.0,"type":["clay","loam"],"drainage":"poor"}',135,'High','Aromatic short-grain rice with golden hue when cooked. Traditional variety of Bihar and Bengal. Mild sweet fragrance. Ideal for khichdi, pulao, and festive dishes. Low yield but premium market price.');
